window.bookSummaryJSON = "<p>*From a <i>USA Today</i> bestselling author comes the exciting continuation of the Mind Dimensions series* </p> <p>Kidnapped. Consciousness expanded. And that was just the start of my day. </p> <p>I always thought I was a nice enough guy. The kind who’d never want to commit murder.</p> <p>Turns out I simply lacked incentive. </p> <p>Some crimes can never be forgiven.</p>"; 
